//! `monte_carlo` — Monte-Carlo robustness harness for v1 cross-sectional
//! momentum (C2).
//!
//! Runs `MomentumStrategy` at its shipped `θ*` over N bootstrap paths
//! generated by C1's `BlockBootstrapPathGen` (or `GbmPathGen` for smoke
//! tests), reduces the N per-path metrics to a `DistributionSummary`, and
//! emits ONE anchored `robustness-*.md` report under
//! `evidence/v1/strategy-robustness-harness/reports/`.
//!
//! ## ADR-0051 compliance
//!
//! - **D1 seed**: `path_seed_j = ensemble_seed.wrapping_add(j * 0x9E37_79B9)`.
//!   Bound to index `j`, NOT completion order.
//! - **D2 reduction**: index-order sequential mean + two-pass std +
//!   `total_cmp` sort + type-7 linear percentile. Parallel fan-out, sequential
//!   reduction. See `backtest::stats::DistributionSummary`.
//! - **D3 report**: YAML front-matter (run-varying, NOT hashed) + deterministic
//!   body (every distribution input + per-metric table at fixed precision).
//! - **D4 anchor**: ONE summary report per scenario under `mc-robustness-2026-06`.
//! - **D5 scope**: byte-identical on the Apple-Silicon canonical box;
//!   cross-platform NOT contracted (inherits ADR-0043).
//!
//! ## Usage
//!
//! ```bash
//! # Block-bootstrap real-data scenario (N=500, --features candle,realdata):
//! cargo run --release -p backtest --features "candle realdata" --bin monte_carlo -- \
//!   --generator block-bootstrap-real \
//!   --paths 500 \
//!   --ensemble-seed 0xC0FFEE \
//!   --out-dir evidence/v1/strategy-robustness-harness/reports/
//!
//! # GBM smoke test (N=50, no realdata feature needed):
//! cargo run --release -p backtest --bin monte_carlo -- \
//!   --generator gbm-smoke \
//!   --paths 50 \
//!   --out-dir /tmp/
//! ```
//!
//! ## Watch recipe (for long-running N=500 runs — copy-paste to operator terminal)
//!
//! ```bash
//! watch -n 10 '
//! PID=$(pgrep -f monte_carlo | head -1)
//! [ -z "$PID" ] && echo "monte_carlo not running" && exit
//! N=$(ls evidence/v1/strategy-robustness-harness/reports/robustness-*.md 2>/dev/null | wc -l | tr -d " ")
//! ELAPSED=$(ps -o etime= -p $PID 2>/dev/null | awk "{gsub(/^ +/,\"\"); n=split(\$0,a,/[-:]/); if(n==2)print a[1]*60+a[2]; else if(n==3)print a[1]*3600+a[2]*60+a[3]; else if(n==4)print a[1]*86400+a[2]*3600+a[3]*60+a[4]}")
//! [ "$N" -gt 0 ] && echo "report landed ($N file(s)); elapsed ${ELAPSED}s" || echo "running (no report yet); elapsed ${ELAPSED}s"
//! '
//! ```
//!
//! ## Cross-references
//!
//! - `spec/v1/strategy-robustness-harness/feature.md` § Design D-C2.1..D-C2.9
//! - `spec/architecture/adr/0051-monte-carlo-determinism-and-distribution-report-anchoring.md`
//! - `crates/data/src/synth/` — C1 path generators consumed here.
//! - `crates/backtest/src/scenarios/montecarlo.rs` — `run_path` cell wrapper.
//! - `crates/backtest/src/stats/` — `DistributionSummary` reducer.

use std::path::PathBuf;

use anyhow::{Context, Result};
use clap::Parser;
use tracing::info;

// The fan-out seam (GeneratorKind, seed derivations, run_one_path,
// run_ensemble) lives in the library (review 1-14) so the R-NR.6/FP-C2.1
// e2e gates exercise the REAL harness chain. This bin is a thin driver.
use backtest::mc_harness::{self, GeneratorKind};

// ── CLI ───────────────────────────────────────────────────────────────────────

#[derive(Parser, Debug)]
#[command(
    name = "monte_carlo",
    about = "Monte-Carlo robustness harness: run v1 momentum over N bootstrap paths → distribution summary",
    long_about = "Generates N synthetic price paths via C1's BlockBootstrapPathGen \
                  (or GbmPathGen for smoke tests), runs the plain v1 cross-sectional \
                  momentum strategy over each path, reduces the N per-path outcomes to \
                  a DistributionSummary (ADR-0051 D2), and emits ONE anchored \
                  robustness-*.md report per ADR-0051 D3/D4."
)]
struct Args {
    /// Path generator to use.
    #[arg(long, value_enum, default_value = "block-bootstrap-real")]
    generator: GeneratorKind,

    /// Number of bootstrap paths (N). Default 500 per Q-RH-1 ratification.
    /// N is a hashed body field — changing N changes the anchor SHA.
    #[arg(long, default_value_t = 500)]
    paths: usize,

    /// Master ensemble seed (hex or decimal). Path j gets seed
    /// `ensemble_seed.wrapping_add(j * 0x9E3779B9)` (ADR-0051 D1).
    #[arg(long, default_value = "0xC0FFEE")]
    ensemble_seed: String,

    /// Parquet root for real OHLCV bars (block-bootstrap-real only).
    #[arg(long, default_value = "data/binance/")]
    data_root: PathBuf,

    /// Pinned data revision SHA.
    #[arg(
        long,
        default_value = "3a8b96c43f2d8980fd8039303197ff3ac5d01e8f9cebaecdf74c853622dbbfc7"
    )]
    expected_revision_sha: String,

    /// Output directory for the robustness report.
    #[arg(
        long,
        default_value = "evidence/v1/strategy-robustness-harness/reports/"
    )]
    out_dir: PathBuf,

    /// Calendar year for the scenario's backtest span (2023 or 2024).
    /// Any other year is rejected (review 1-14 — no silent 8760 fallback).
    #[arg(long, default_value_t = 2023)]
    year: i32,
}

// ── Seed helpers ──────────────────────────────────────────────────────────────

/// Parse an ensemble seed from a hex string (0x…) or decimal string.
fn parse_seed(s: &str) -> Result<u64> {
    let s = s.trim();
    if let Some(hex) = s.strip_prefix("0x").or_else(|| s.strip_prefix("0X")) {
        u64::from_str_radix(hex, 16).with_context(|| format!("parse hex seed: {s}"))
    } else {
        s.parse::<u64>()
            .with_context(|| format!("parse decimal seed: {s}"))
    }
}

// ── Git / hostname helpers (mirrors threshold_sweep) ──────────────────────────

fn read_git_commit() -> String {
    std::process::Command::new("git")
        .args(["rev-parse", "HEAD"])
        .output()
        .ok()
        .and_then(|o| String::from_utf8(o.stdout).ok())
        .map(|s| s.trim().to_string())
        .filter(|s| !s.is_empty())
        .unwrap_or_else(|| "unknown".to_string())
}

fn read_hostname() -> String {
    std::process::Command::new("hostname")
        .output()
        .ok()
        .and_then(|o| String::from_utf8(o.stdout).ok())
        .map(|s| s.trim().to_string())
        .filter(|s| !s.is_empty())
        .unwrap_or_else(|| std::env::var("HOSTNAME").unwrap_or_else(|_| "unknown".to_string()))
}

fn read_data_revision_sha(data_root: &std::path::Path) -> String {
    let rev_path = data_root.join("REVISION.toml");
    std::fs::read_to_string(&rev_path)
        .ok()
        .and_then(|s| {
            s.lines()
                .find(|l| l.starts_with("sha"))
                .and_then(|l| l.split('=').nth(1))
                .map(|v| v.trim().trim_matches('"').to_string())
        })
        .unwrap_or_else(|| "unknown".to_string())
}

/// Per-symbol source bar collection (type alias to reduce complexity).
type SourceBars = Vec<(trading_core::Symbol, Vec<trading_core::Bar>)>;

/// Result of loading source bars: bars by symbol + revision SHA string.
type SourceBarsResult = Result<(SourceBars, String)>;

// ── Report renderer (ADR-0051 D3) ─────────────────────────────────────────────

/// Render the robustness distribution-summary markdown report.
///
/// Front-matter (run-varying, NOT hashed) + deterministic body (every
/// distribution input + per-metric table at fixed precision + prob-of-loss
/// block). Mirrors the threshold_sweep report structure per D3.
#[allow(clippy::too_many_arguments)]
fn render_report(
    // Front-matter (run-varying)
    generated: &str,
    wall_clock_s: f64,
    host: &str,
    pid: u32,
    git_commit: &str,
    data_revision_sha: &str,
    scenario: &str,
    // Body (deterministic, hashed)
    master_seed: u64,
    fill_seed: u64,
    n_paths: usize,
    generator_label: &str,
    bootstrap_mode: &str,
    block_length_policy: &str,
    selected_block_length_l: Option<usize>,
    source_revision_sha: &str,
    param_set: &str,
    summary: &backtest::stats::DistributionSummary,
) -> String {
    // ── Front-matter (NOT hashed) ─────────────────────────────────────────────
    let frontmatter = format!(
        "---\n\
         slug: strategy-robustness-harness\n\
         scenario: {scenario}\n\
         generated: {generated}\n\
         wall_clock_s: {wall_clock_s:.1}\n\
         host: {host}\n\
         pid: {pid}\n\
         git_commit: {git_commit}\n\
         data_revision_sha: {data_revision_sha}\n\
         ---\n"
    );

    // ── Body (deterministic, hashed by the anchor) ────────────────────────────
    let mut body = String::new();

    body.push_str(&format!(
        "# Monte-Carlo Robustness Summary — {scenario}\n\n"
    ));

    // Distribution inputs (every one changes the SHA if changed — K3 / D3).
    body.push_str("## Ensemble parameters\n\n");
    body.push_str("| Field                    | Value                                      |\n");
    body.push_str("|--------------------------|--------------------------------------------|\n");
    body.push_str(&format!(
        "| master_seed              | 0x{master_seed:X}                             |\n"
    ));
    body.push_str(&format!(
        "| fill_seed                | 0x{fill_seed:X}                             |\n"
    ));
    body.push_str(&format!(
        "| n_paths                  | {n_paths}                                   |\n"
    ));
    body.push_str("| sub_seed_rule            | \"master + j*0x9E3779B9\"                    |\n");
    body.push_str("| reduction_rule           | \"index-order mean/std; total_cmp sort; type-7 linear pct\" |\n");
    body.push_str(&format!(
        "| generator                | {generator_label}                          |\n"
    ));
    body.push_str(&format!(
        "| bootstrap_mode           | {bootstrap_mode}                           |\n"
    ));
    body.push_str(&format!(
        "| block_length_policy      | {block_length_policy}                      |\n"
    ));
    if let Some(l) = selected_block_length_l {
        body.push_str(&format!(
            "| selected_block_length_L  | {l}                                         |\n"
        ));
    } else {
        body.push_str(
            "| selected_block_length_L  | N/A                                        |\n",
        );
    }
    body.push_str(&format!(
        "| source_revision_sha      | {source_revision_sha}                      |\n"
    ));
    body.push_str(&format!(
        "| param_set                | {param_set}                                |\n"
    ));
    body.push('\n');

    // Per-metric distribution table (FIXED metric order: sharpe/sortino/calmar/max_drawdown/total_return).
    body.push_str("## Per-metric distribution\n\n");
    body.push_str("| metric       | mean     | std      | p5       | p25      | p50      | p75      | p95      | min      | max      |\n");
    body.push_str("|--------------|----------|----------|----------|----------|----------|----------|----------|----------|----------|\n");

    let fmt_metric_row = |name: &str, d: &backtest::stats::MetricDistribution| -> String {
        format!(
            "| {name:<12} | {:.6} | {:.6} | {:.6} | {:.6} | {:.6} | {:.6} | {:.6} | {:.6} | {:.6} |\n",
            d.mean, d.std, d.p5, d.p25, d.p50, d.p75, d.p95, d.min, d.max
        )
    };

    body.push_str(&fmt_metric_row("sharpe", &summary.sharpe));
    body.push_str(&fmt_metric_row("sortino", &summary.sortino));
    body.push_str(&fmt_metric_row("calmar", &summary.calmar));

    // max_drawdown uses {:.2}% per ADR-0051 D3 / threshold_sweep convention.
    body.push_str(&format!(
        "| {:<12} | {:.2}% | {:.2}% | {:.2}% | {:.2}% | {:.2}% | {:.2}% | {:.2}% | {:.2}% | {:.2}% |\n",
        "max_drawdown",
        summary.max_drawdown.mean * 100.0,
        summary.max_drawdown.std * 100.0,
        summary.max_drawdown.p5 * 100.0,
        summary.max_drawdown.p25 * 100.0,
        summary.max_drawdown.p50 * 100.0,
        summary.max_drawdown.p75 * 100.0,
        summary.max_drawdown.p95 * 100.0,
        summary.max_drawdown.min * 100.0,
        summary.max_drawdown.max * 100.0,
    ));
    body.push_str(&fmt_metric_row("total_return", &summary.total_return));
    body.push('\n');

    // Ensemble robustness block.
    body.push_str("## Ensemble robustness\n\n");
    body.push_str("| Field                          | Value       |\n");
    body.push_str("|--------------------------------|-------------|\n");
    body.push_str(&format!(
        "| P(final_equity < initial)      | {:.6} |\n",
        summary.prob_loss
    ));
    body.push_str(&format!(
        "| P(Sharpe > 0)                  | {:.6} |\n",
        summary.prob_sharpe_gt_0
    ));
    body.push_str(&format!(
        "| P(Sharpe > 1.0)                | {:.6} |\n",
        summary.prob_sharpe_gt_1
    ));
    body.push_str(&format!(
        "| max_drawdown_tail p50          | {:.2}% |\n",
        summary.max_dd_tail_p50 * 100.0
    ));
    body.push_str(&format!(
        "| max_drawdown_tail p95          | {:.2}% |\n",
        summary.max_dd_tail_p95 * 100.0
    ));
    body.push('\n');

    // Verdict — directional summary of the distribution.
    let sharpe_p50 = summary.sharpe.p50;
    let sharpe_spread = summary.sharpe.p95 - summary.sharpe.p5;
    let verdict_str = if sharpe_p50 > 1.0 {
        "ROBUST-ABOVE-1: p50 Sharpe > 1.0 — ensemble median clears the paper→live gate"
    } else if sharpe_p50 > 0.0 {
        "MARGINAL: p50 Sharpe in (0, 1.0] — median is positive but below the paper→live gate"
    } else {
        "WEAK: p50 Sharpe ≤ 0 — ensemble median is non-positive"
    };

    body.push_str("## Verdict\n\n");
    body.push_str(&format!("Sharpe p50: {sharpe_p50:.6}\n"));
    body.push_str(&format!("Sharpe spread (p95-p5): {sharpe_spread:.6}\n"));
    body.push_str(&format!("Verdict: {verdict_str}\n\n"));

    body.push_str("Notes:\n");
    body.push_str("- Drawdown tail (p95 MaxDD) is the headline paper→live gate number.\n");
    body.push_str(&format!(
        "- Generator: `{generator_label}` (only `block-bootstrap-real` is anchor-grade).\n"
    ));
    body.push_str("- Determinism scope: Apple-Silicon canonical box (ADR-0051 D5).\n");

    format!("{frontmatter}{body}")
}

// ── Main ──────────────────────────────────────────────────────────────────────

fn main() -> Result<()> {
    // Build a dedicated rayon thread pool (mirrors threshold_sweep sweep_pool pattern).
    let mc_pool = rayon::ThreadPoolBuilder::new()
        .build()
        .context("build rayon mc thread pool")?;

    llm::tracing_init::install_global(&[], false).ok();

    let args = Args::parse();
    let start = std::time::Instant::now();

    info!(
        generator = args.generator.label(),
        n_paths = args.paths,
        ensemble_seed = %args.ensemble_seed,
        "monte_carlo: starting"
    );

    let ensemble_seed = parse_seed(&args.ensemble_seed).context("parse --ensemble-seed")?;

    // Review 1-14: validate --paths (≥ 2, sane cap) before any heavy work.
    mc_harness::validate_paths(args.paths)?;

    // Fixed fill-tie-break seed (ADR-0051 D1: held constant across all paths).
    const FILL_SEED: u64 = 0xC0FFEE;

    // Review 1-14: bail on unmapped years (no silent leap-wrong 8760 fallback).
    let bar_count = mc_harness::bar_count_for_year(args.year)?;

    let symbols_prices = backtest::scenarios::momentum::top10_symbols_with_prices();
    let universe: Vec<(trading_core::Symbol, rust_decimal::Decimal)> = symbols_prices.clone();

    // ── Load real bars (block-bootstrap-real only) ────────────────────────────
    #[cfg(not(feature = "realdata"))]
    if args.generator == GeneratorKind::BlockBootstrapReal {
        anyhow::bail!(
            "monte_carlo --generator block-bootstrap-real requires --features realdata. \
             Rebuild with: cargo run -p backtest --features candle,realdata --bin monte_carlo -- ..."
        );
    }

    let (real_bars_by_symbol, source_revision_sha) =
        load_source_bars(&args, &symbols_prices, bar_count)?;

    // ── Auto block length from source for body (deterministic input printing) ──
    // For gbm-smoke, there are no real bars; for block-bootstrap-real, compute
    // the selected L so we can print it in the hashed body.
    let (generator_label, bootstrap_mode, block_length_policy_str, selected_l) =
        prepare_generator_params(args.generator, &real_bars_by_symbol, ensemble_seed)?;

    // ── Fan out over N paths in parallel + reduce (ADR-0051 D1/D2) ────────────
    // The production fan-out → sort-by-j → reduce chain lives in
    // `backtest::mc_harness::run_ensemble` (review 1-14 seam extraction) so
    // the e2e gates exercise it directly. Seeds are bound to index j; rayon
    // completion order affects neither seeds nor reduction order.
    info!(n_paths = args.paths, "fan-out starting");

    let (_metrics, summary) = mc_pool.install(|| {
        mc_harness::run_ensemble(
            args.paths,
            ensemble_seed,
            FILL_SEED,
            &universe,
            &real_bars_by_symbol,
            bar_count,
            args.generator,
            args.year,
        )
    })?;

    info!(n_paths = args.paths, "fan-out + reduction complete");

    let wall_clock_s = start.elapsed().as_secs_f64();
    info!(
        wall_clock_s,
        sharpe_p50 = summary.sharpe.p50,
        sharpe_p5 = summary.sharpe.p5,
        sharpe_p95 = summary.sharpe.p95,
        prob_loss = summary.prob_loss,
        max_dd_p95 = summary.max_dd_tail_p95,
        "monte_carlo: reduction complete"
    );

    // ── Build param_set string (hashed body — K3: changing θ* changes the SHA)
    let param_set = build_param_set()?;

    // ── Generate timestamps (review 1-14: ONE clock read shared by the
    //    front-matter `generated` field and the report filename, so the two
    //    can never straddle midnight/a second boundary) ─────────────────────
    let (generated, ts_suffix) = {
        let now = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap_or_default()
            .as_secs();
        let secs_of_day = now % 86400;
        let hours = secs_of_day / 3600;
        let mins = secs_of_day / 60 % 60;
        let secs = secs_of_day % 60;
        // Use today's date (approximate from epoch seconds).
        let days_since_epoch = now / 86400;
        let (y, m, d) = days_since_epoch_to_ymd(days_since_epoch);
        (
            format!("{y:04}-{m:02}-{d:02}T{hours:02}:{mins:02}:{secs:02}Z"),
            format!("{y:04}{m:02}{d:02}-{hours:02}{mins:02}{secs:02}"),
        )
    };
    let host = read_hostname();
    let git_commit = read_git_commit();
    let data_rev_frontmatter = read_data_revision_sha(&args.data_root);
    let pid = std::process::id();
    // Review 1-14: honest scenario naming — the gbm-smoke lane no longer
    // carries a false "block-bootstrap" token; the anchored lane's NAME is
    // byte-identical (pinned by a regression test in tests/montecarlo_e2e.rs).
    let scenario_name = mc_harness::scenario_name(args.generator, args.year);

    // ── Render report (ADR-0051 D3) ───────────────────────────────────────────
    let report = render_report(
        &generated,
        wall_clock_s,
        &host,
        pid,
        &git_commit,
        &data_rev_frontmatter,
        &scenario_name,
        ensemble_seed,
        FILL_SEED,
        args.paths,
        &generator_label,
        &bootstrap_mode,
        &block_length_policy_str,
        selected_l,
        &source_revision_sha,
        &param_set,
        &summary,
    );

    // ── Write report ──────────────────────────────────────────────────────────
    std::fs::create_dir_all(&args.out_dir)
        .with_context(|| format!("create out_dir {:?}", args.out_dir))?;

    // Filename timestamp: same single clock read as the front-matter above.
    let report_filename = format!("robustness-{ts_suffix}-{scenario_name}.md");
    let report_path = args.out_dir.join(&report_filename);
    std::fs::write(&report_path, &report)
        .with_context(|| format!("write report to {:?}", report_path))?;

    // Compute body SHA for the operator (tester will lock it).
    let body_sha = {
        use sha2::{Digest, Sha256};
        let body = backtest::extract_report_body(&report);
        let mut hasher = Sha256::new();
        hasher.update(body.as_bytes());
        hasher.finalize().iter().fold(String::new(), |mut s, b| {
            use std::fmt::Write as _;
            let _ = write!(s, "{b:02x}");
            s
        })
    };

    info!(
        scenario = %scenario_name,
        n_paths = args.paths,
        wall_clock_s,
        sharpe_p5 = summary.sharpe.p5,
        sharpe_p50 = summary.sharpe.p50,
        sharpe_p95 = summary.sharpe.p95,
        max_dd_tail_p95 = summary.max_dd_tail_p95,
        prob_sharpe_gt_1 = summary.prob_sharpe_gt_1,
        report = %report_path.display(),
        body_sha = %body_sha,
        "monte_carlo: DONE"
    );

    // Print headline to stdout for operator visibility.
    println!("monte_carlo DONE");
    println!("  report:       {}", report_path.display());
    println!("  body_sha:     {body_sha}");
    println!("  wall_clock_s: {wall_clock_s:.1}");
    println!("  n_paths:      {}", args.paths);
    println!(
        "  sharpe p5/p50/p95: {:.4} / {:.4} / {:.4}",
        summary.sharpe.p5, summary.sharpe.p50, summary.sharpe.p95
    );
    println!(
        "  max_dd tail p50/p95: {:.2}% / {:.2}%",
        summary.max_dd_tail_p50 * 100.0,
        summary.max_dd_tail_p95 * 100.0
    );
    println!(
        "  P(loss): {:.4}  P(Sharpe>0): {:.4}  P(Sharpe>1): {:.4}",
        summary.prob_loss, summary.prob_sharpe_gt_0, summary.prob_sharpe_gt_1
    );

    Ok(())
}

// ─────────────────────────────────────────────────────────────────────────────
// Helpers
// ─────────────────────────────────────────────────────────────────────────────

/// Load source bars for the given generator kind.
///
/// Returns `(bars_by_symbol, source_revision_sha)`.
/// For `GbmSmoke`, generates synthetic bars (no real data needed); returns
/// `("gbm-smoke-internal", "N/A")`.
fn load_source_bars(
    args: &Args,
    symbols_prices: &[(trading_core::Symbol, rust_decimal::Decimal)],
    bar_count: usize,
) -> SourceBarsResult {
    match args.generator {
        GeneratorKind::GbmSmoke => {
            // Generate synthetic bars for GBM smoke test.
            let bars_by_symbol: Vec<(trading_core::Symbol, Vec<trading_core::Bar>)> =
                symbols_prices
                    .iter()
                    .enumerate()
                    .map(|(idx, (sym, start_price))| {
                        // Review 1-14: dedicated source-bar seed base, SplitMix64-mixed —
                        // the old `0xC0FFEE + idx·0x9E37_79B9` was bit-identical to the
                        // ADR-0051 D1 path-seed family at the default master seed.
                        let sym_seed =
                            mc_harness::derive_gbm_sym_seed(mc_harness::GBM_SOURCE_SEED_BASE, idx);
                        let bars = backtest::scenarios::momentum::synthetic_bars_hourly(
                            sym,
                            bar_count,
                            sym_seed,
                            *start_price,
                            args.year,
                        );
                        (sym.clone(), bars)
                    })
                    .collect();
            Ok((bars_by_symbol, "N/A".to_string()))
        }
        GeneratorKind::BlockBootstrapReal => load_real_bars(args, symbols_prices, bar_count),
    }
}

/// Load real Binance bars (realdata feature gate).
#[cfg(feature = "realdata")]
fn load_real_bars(
    args: &Args,
    symbols_prices: &[(trading_core::Symbol, rust_decimal::Decimal)],
    bar_count: usize,
) -> SourceBarsResult {
    use backtest::realdata::{RealDataBarSource, TimeSpan as RealDataTimeSpan};

    let symbols: Vec<trading_core::Symbol> =
        symbols_prices.iter().map(|(s, _)| s.clone()).collect();
    let src = RealDataBarSource::new(args.data_root.clone(), symbols.clone());
    let span = RealDataTimeSpan::full_year(args.year);
    let expected_total = bar_count * symbols.len();
    let scenario_name = format!("monte-carlo-load-{}", args.year);
    let loaded = src
        .load(span, expected_total, &scenario_name)
        .map_err(|e| anyhow::anyhow!("load real bars: {e}"))?;

    // Verify pinned revision SHA.
    if loaded.revision_sha != args.expected_revision_sha {
        anyhow::bail!(
            "data revision mismatch: expected {} but computed {}",
            args.expected_revision_sha,
            loaded.revision_sha
        );
    }

    let revision_sha = loaded.revision_sha.clone();
    info!(
        bar_count = loaded.loaded_count,
        revision_sha = %revision_sha,
        "real bars loaded"
    );

    // Split the merged bars back into per-symbol series.
    // The RealDataBarSource returns a merged flat Vec<Bar>; we need per-symbol.
    // Use the ordering from symbols_prices.
    let merged_bars = loaded.bars;
    let mut by_symbol: std::collections::BTreeMap<String, Vec<trading_core::Bar>> =
        std::collections::BTreeMap::new();
    for bar in merged_bars {
        by_symbol
            .entry(bar.symbol.to_string())
            .or_default()
            .push(bar);
    }

    // Sort each symbol's bars by open_ts to ensure consistent ordering.
    for bars in by_symbol.values_mut() {
        bars.sort_by_key(|b| b.open_ts);
    }

    let bars_by_symbol: Vec<(trading_core::Symbol, Vec<trading_core::Bar>)> = symbols_prices
        .iter()
        .map(|(sym, _)| {
            let bars = by_symbol.remove(&sym.to_string()).unwrap_or_default();
            (sym.clone(), bars)
        })
        .collect();

    Ok((bars_by_symbol, revision_sha))
}

/// Stub for non-realdata builds (only GbmSmoke is allowed without the feature).
#[cfg(not(feature = "realdata"))]
fn load_real_bars(
    _args: &Args,
    _symbols_prices: &[(trading_core::Symbol, rust_decimal::Decimal)],
    _bar_count: usize,
) -> SourceBarsResult {
    anyhow::bail!(
        "load_real_bars called without --features realdata. \
         Use --generator gbm-smoke or rebuild with the realdata feature."
    )
}

/// Build the generator label + bootstrap_mode + block_length_policy + selected_L.
fn prepare_generator_params(
    generator: GeneratorKind,
    real_bars_by_symbol: &[(trading_core::Symbol, Vec<trading_core::Bar>)],
    _ensemble_seed: u64,
) -> Result<(String, String, String, Option<usize>)> {
    match generator {
        GeneratorKind::GbmSmoke => Ok((
            "gbm-smoke".to_string(),
            "N/A".to_string(),
            "N/A".to_string(),
            None,
        )),
        GeneratorKind::BlockBootstrapReal => {
            // Build the path generator to get the auto-selected L (deterministic from
            // the source series — same as the L used for path 0).
            let source: Vec<(trading_core::Symbol, Vec<trading_core::Bar>)> =
                real_bars_by_symbol.to_vec();
            let path_gen = data::BlockBootstrapPathGen::new(source, data::BlockLengthPolicy::Auto)
                .context("build BlockBootstrapPathGen to get selected_L")?;

            let universe: Vec<(trading_core::Symbol, rust_decimal::Decimal)> = real_bars_by_symbol
                .iter()
                .map(|(sym, bars)| {
                    let start = bars
                        .first()
                        .map(|b| b.close.get())
                        .unwrap_or(rust_decimal_macros::dec!(1));
                    (sym.clone(), start)
                })
                .collect();

            // Generate one probe path to extract selected_L.
            use data::MonteCarloPathGen as _;
            let probe = path_gen
                .generate(&universe, 10, _ensemble_seed)
                .context("probe generate for selected_L")?;
            let selected_l = probe.selected_block_length;

            Ok((
                "block-bootstrap-real".to_string(),
                "shared-index".to_string(),
                "auto".to_string(),
                selected_l,
            ))
        }
    }
}

/// Build the `param_set` string from the shipped strategy config (hashed body field — K3).
fn build_param_set() -> Result<String> {
    let rel_path = std::path::PathBuf::from("config/strategies/top10_momentum_h1.toml");
    let toml_path = backtest::paths::resolve_workspace_path(&rel_path);
    let cfg = strategy::CrossSectionalMomentumConfig::from_file(&toml_path)
        .with_context(|| format!("load momentum config for param_set: {}", rel_path.display()))?;
    Ok(format!(
        "lookback={} rebalance={} k_long={} exposure_cap={} drift={} vol_floor={}",
        cfg.lookback_minutes,
        cfg.rebalance_minutes,
        cfg.k_long,
        cfg.exposure_cap,
        cfg.drift_rebalance_threshold,
        cfg.vol_floor,
    ))
}

/// Simple Gregorian calendar conversion (days since 1970-01-01 → y/m/d).
/// Good enough for the advisory front-matter timestamp.
#[allow(clippy::cast_possible_truncation)]
fn days_since_epoch_to_ymd(days: u64) -> (u32, u32, u32) {
    // Use the algorithm from https://howardhinnant.github.io/date_algorithms.html
    let z = days as i64 + 719_468;
    let era = (if z >= 0 { z } else { z - 146_096 }) / 146_097;
    let doe = z - era * 146_097;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146_096) / 365;
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    let y_adj = if m <= 2 { y + 1 } else { y };
    (y_adj as u32, m as u32, d as u32)
}
